const wrap = (body, sky = '#e5efff') => `<svg viewBox="0 0 400 390" role="img" aria-label="아이의 이야기를 표현한 풍경 그림"><rect width="400" height="390" fill="${sky}"/>${body}</svg>`;
const clouds = '<path d="M50 100c-18-5-15-27 3-29 0-27 42-32 50-5 23-3 31 25 10 32Z" fill="#fff"/><path d="M253 143c-13-4-11-20 2-22 0-21 32-24 38-4 18-2 24 19 8 24Z" fill="#fff"/>';
const hills = '<path d="M0 278q110-90 230-15t170-14v141H0Z" fill="#b5cccb"/><path d="M0 326q125-89 250-12t150-10v86H0Z" fill="#86aca5"/>';
const sun = '<circle cx="305" cy="75" r="29" fill="#f6d993"/>';
const road = '<path d="M103 390q60-92 297-107" stroke="#ece6cf" stroke-width="42" fill="none"/>';
const star = (x,y,s=1) => `<path d="m${x} ${y-8*s} 2 6 6 2-6 2-2 6-2-6-6-2 6-2Z" fill="#ffdc97"/>`;
export function storyScene(key='custom') {
  if (key === 'space') return wrap(`${Array.from({length:12},(_,i)=>star(30+(i*67)%350,32+(i*53)%290,.8)).join('')}<circle cx="283" cy="286" r="81" fill="#a7b8ed"/><ellipse cx="283" cy="286" rx="124" ry="26" fill="none" stroke="#d3ddfc" stroke-width="13" transform="rotate(-24 283 286)"/><g transform="translate(104 130) rotate(24)"><path d="M0 48Q5-5 29-30Q53-5 58 48Z" fill="#fff"/><circle cx="29" cy="14" r="12" fill="#79a7f5"/><path d="m8 50 21 39 21-39" fill="#f6cd82"/><path d="m0 33-15 28 24-7m49-21 15 28-24-7" fill="#6a8ee0"/></g>`, '#253960');
  if (key === 'night') return wrap(`<path d="M305 45a46 46 0 1 0 28 79 41 41 0 0 1-28-79" fill="#ffdf99"/>${[star(70,63),star(181,117),star(83,194),star(280,180),star(350,238)].join('')}${hills}`, '#344d76');
  if (key === 'tunnel') return wrap(`<path d="M0 390V189a200 170 0 0 1 400 0v201Z" fill="#aab8cb"/><path d="M33 390V193a167 139 0 0 1 334 0v197Z" fill="#778ba8"/><path d="M77 390V205a123 106 0 0 1 246 0v185Z" fill="#526c94"/><path d="M119 390V220a81 74 0 0 1 162 0v170Z" fill="#deeaf8"/><path d="m87 390 95-176h36l95 176" fill="#a8b8cb"/><path d="M200 236v22m0 20v26m0 25v35" stroke="#fff3cc" stroke-width="4"/><path d="M96 100h18m173 0h18M61 183h13m253 0h13" stroke="#fff1c4" stroke-width="9" stroke-linecap="round"/>`, '#e3ebf6');
  if (key === 'water') return wrap(`${sun}${clouds}<path d="M0 238q50-15 100 0t100 0 100 0 100 0v152H0Z" fill="#97c5da"/><path d="M0 287q50-15 100 0t100 0 100 0 100 0v103H0Z" fill="#6ca7c7"/><path d="M-15 338q50-15 100 0t100 0 100 0 100 0" fill="none" stroke="#c0e0ed" stroke-width="5"/><path d="m150 253 27 29h83l27-29Z" fill="#f4e2bc"/><path d="M217 149v103m-8-98-54 80h54Z" fill="#fff" stroke="#d2deeb" stroke-width="3"/>`);
  if (key === 'mountain') return wrap(`${sun}${clouds}<path d="m-30 355 169-217 127 179 64-151 110 189" fill="#a7b8ca"/><path d="m89 204 50-66 50 71-45-15-28 21Z" fill="#fff"/><path d="m255 390 75-224 99 224" fill="#7c9aa9"/><path d="m310 226 20-60 31 70-28-13Z" fill="#e6eef4"/>${hills}`);
  if (key === 'city') return wrap(`${sun}${clouds}${[[23,173,74,172],[114,135,70,208],[207,202,63,141],[292,155,83,189]].map(([x,y,w,h],i)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="7" fill="${['#b9c7d9','#a4b9d3','#c7c5bd','#adbdc7'][i]}"/>${Array.from({length:4},(_,r)=>`<path d="M${x+15} ${y+20+r*29}h12m12 0h12" stroke="#f9f4dc" stroke-width="12"/>`).join('')}`).join('')}<path d="M0 345h400v45H0Z" fill="#aab6c5"/><path d="M0 369h400" stroke="#edf2fb" stroke-width="3" stroke-dasharray="20 18"/>`);
  if (key === 'forest') return wrap(`${sun}${clouds}${hills}${[[55,200,1],[160,243,.8],[269,225,.9],[360,265,.6]].map(([x,y,s])=>`<g transform="translate(${x} ${y}) scale(${s})"><path d="M0 0v110" stroke="#6a8f8c" stroke-width="9"/><path d="M-40 12c-32-30-15-70 11-70-9-35 39-55 56-24 41-10 57 45 28 63 4 38-63 61-95 31Z" fill="#8fb3a5"/><path d="M-18-22q-7-18 6-30" stroke="#b7d1bf" stroke-width="6" fill="none" stroke-linecap="round"/></g>`).join('')}${road}`);
  if (key === 'road') return wrap(`${sun}${clouds}${hills}${road}<g transform="translate(253 286)"><path d="m-35 2 12-20h42l17 20 7 6v23h-88V8Z" fill="#b1c8e8"/><path d="m-18-12-7 14h49l-13-14Z" fill="#eef4ff"/><circle cx="-25" cy="30" r="9" fill="#4b6485"/><circle cx="25" cy="30" r="9" fill="#4b6485"/></g>`);
  return wrap(`${sun}${clouds}<path d="M75 214c-31-4-37-42-9-52 5-43 62-49 77-12 32-12 57 17 44 44 38-5 53 36 24 52H85c-24-3-29-22-10-32Z" fill="#fff" opacity=".9"/>${hills}`);
}
